module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    // State encoding: 4 states to cover the sequence 1101 detection
    typedef enum logic [1:0] {
        S_IDLE   = 2'b00, // Waiting for the first '1'
        S_1      = 2'b01, // Matched first '1'
        S_10     = 2'b10, // Matched '10' after first '1'
        S_101    = 2'b11  // Matched '101', next bit '1' completes '1101'
    } state_t;

    state_t state, next_state;

    // State register (synchronous reset)
    always_ff @(posedge clk) begin
        if (reset)
            state <= S_IDLE;
        else
            state <= next_state;
    end

    // Next-state logic
    always_comb begin
        case (state)
            S_IDLE: begin
                if (data == 1'b1)
                    next_state = S_1;
                else
                    next_state = S_IDLE;
            end
            S_1: begin
                if (data == 1'b1)
                    next_state = S_10; // Second '1' received, expecting '0'
                else
                    next_state = S_IDLE; // Received '0', reset to start
            end
            S_10: begin
                if (data == 1'b1)
                    next_state = S_101; // Received '1' after '10', expecting '1' to complete '1101'
                else
                    next_state = S_IDLE; // Received '0', sequence broken
            end
            S_101: begin
                if (data == 1'b1)
                    next_state = S_1;   // Sequence '1101' found. Stay in a state that allows re-detection or loop.
                else
                    next_state = S_IDLE; // Sequence broken
            end
            default: next_state = S_IDLE;
        endcase
    end

    // Output logic
    // start_shifting is set to 1 when the full sequence 1101 is detected.
    // It remains 1 forever until reset.
    assign start_shifting = (state == S_101) & (data == 1'b1);

endmodule

