module TopModule (
    input  [3:0] x,
    output       f
);

    // Internal signals for K-map variables
    // x[3] is the most significant bit, x[0] is the least significant
    wire x3 = x[3];
    wire x2 = x[2];
    wire x1 = x[1];
    wire x0 = x[0];

    // Derived variables for K-map rows and columns
    // Row: x3 x0 (00, 01, 11, 10)
    wire row00 = ~x3 & ~x0;
    wire row01 = ~x3 &  x0;
    wire row11 =  x3 &  x0;
    wire row10 =  x3 & ~x0;

    // Column: x1 x2 (00, 01, 11, 10)
    wire col00 = ~x1 & ~x2;
    wire col01 = ~x1 &  x2;
    wire col11 =  x1 &  x2;
    wire col10 =  x1 & ~x2;

    // Minterms and prime implicants derived from the K-map:
    // f = x'3 x'0 x'1 x'2   +   x'3  x1 x2   +   x3 x0 x1 x'2   +   x3 x0 x1 x2
    //     +   x3 x'0 x1 x'2   +   x3 x'0 x1 x2
    // Using don't-care conditions to simplify:
    assign f = (~x3 & ~x0 & ~x1 & ~x2) |        // m0 (d) 
               (~x3 &  x1 &  x2) |              // m5 
               ( x3 &  x0 &  x1 & ~x2) |       // m13
               ( x3 &  x0 &  x1 &  x2) |       // m15
               ( x3 & ~x0 &  x1 & ~x2) |       // m12
               ( x3 & ~x0 &  x1 &  x2);        // m14

