module TopModule (
    input  d,
    input  done_counting,
    input  ack,
    input  state [9:0],
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

    // Internal wires for decoded next-state signals
    wire next_S;
    wire next_S1;
    wire next_S11;
    wire next_S110;
    wire next_B0;
    wire next_B1;
    wire next_B2;
    wire next_B3;
    wire next_Count;
    wire next_Wait;

    // ============================================================
    // Next-state logic (one-hot encoded state, combinational)
    // ============================================================
    // Decode current state
    wire cur_S   = state[0];
    wire cur_S1  = state[1];
    wire cur_S11 = state[2];
    wire cur_S110= state[3];
    wire cur_B0  = state[4];
    wire cur_B1  = state[5];
    wire cur_B2  = state[6];
    wire cur_B3  = state[7];
    wire cur_Count= state[8];
    wire cur_Wait = state[9];

    // Next-state equations derived by inspection (Moore machine)
    // S next-state
    assign next_S   = (cur_S   & ~d) |
                      (cur_S1  & ~d) |
                      (cur_S110& ~d) |
                      (cur_B0  & ~done_counting & ack) |
                      (cur_Wait& ack);

    // S1 next-state
    assign next_S1  = (cur_S   & d) |
                      (cur_S1  & d);

    // S11 next-state
    assign next_S11 = (cur_S1  & d) |
                      (cur_S11 & d);

    // S110 next-state
    assign next_S110= (cur_S11 & ~d);

    // B0 next-state (from S110 with d=1)
    assign next_B0  = (cur_S110 & d);

    // B1 next-state (from B0, always)
    assign next_B1  = cur_B0;

    // B2 next-state (from B1, always)
    assign next_B2  = cur_B1;

    // B3 next-state (from B2, always)
    assign next_B3  = cur_B2;

    // Count next-state (from B3, always)
    assign next_Count= cur_B3;

    // Wait next-state (from Count)
    // Count -> Wait when done_counting=1, else stay in Count
    assign next_Wait= (cur_Count & done_counting);

    // Output assignments for next-state assertion signals
    assign B3_next   = next_B3;
    assign S_next    = next_S;
    assign S1_next   = next_S1;
    assign Count_next= next_Count;
    assign Wait_next = next_Wait;

    // ============================================================
    // Output logic (Moore outputs – depend only on current state)
    // ============================================================
    // done: asserted in Wait state
    assign done = cur_Wait;

    // counting: asserted in Count state
    assign counting = cur_Count;

    // shift_ena: asserted in B0, B1, B2, B3 states
    assign shift_ena = cur_B0 | cur_B1 | cur_B2 | cur_B3;

endmodule

