module TopModule (
    input  clk,
    input  reset,
    output ena   // 3 bits: enable for tens, hundreds, thousands
    output q     // 16 bits: 4-digit BCD
);

    // Internal register for the 4-digit BCD counter (16 bits)
    reg [15:0] q_reg;

    // Assign output ports
    assign q = q_reg;

    // Assign enable signals based on the current BCD state
    // ena[0] enables tens digit increment (ones digit is 9)
    // ena[1] enables hundreds digit increment (tens and ones are 9)
    // ena[2] enables thousands digit increment (hundreds, tens, and ones are 9)
    assign ena = {q_reg[11:8] == 4'd9, q_reg[7:4] == 4'd9, q_reg[3:0] == 4'd9};

    // Synchronous always block for the counter
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            q_reg <= 16'd0;
        end else begin
            // Logic to determine next state for each digit

            // Digit 0 (ones): Always increments. Wraps to 0 if 9.
            wire [3:0] d0_next;
            assign d0_next = (q_reg[3:0] == 4'd9) ? 4'd0 : q_reg[3:0] + 1'b1;

            // Digit 1 (tens): Increments if carry from ones (d0 was 9).
            // If current is 9 and carry is 1, next is 0. Else current + carry.
            wire [3:0] d1_next;
            assign d1_next = (q_reg[3:0] == 4'd9) ? 
                             ((q_reg[7:4] == 4'd9) ? 4'd0 : q_reg[7:4] + 1'b1) : 
                             q_reg[7:4];

            // Digit 2 (hundreds): Increments if carry from tens (d0 and d1 were 9).
            wire [3:0] d2_next;
            assign d2_next = (q_reg[3:0] == 4'd9 & q_reg[7:4] == 4'd9) ? 
                             ((q_reg[11:8] == 4'd9) ? 4'd0 : q_reg[11:8] + 1'b1) : 
                             q_reg[11:8];

            // Digit 3 (thousands): Increments if carry from hundreds (d0, d1, d2 were 9).
            wire [3:0] d3_next;
            assign d3_next = (q_reg[3:0] == 4'd9 & q_reg[7:4] == 4'd9 & q_reg[11:8] == 4'd9) ? 
                             ((q_reg[15:12] == 4'd9) ? 4'd0 : q_reg[15:12] + 1'b1) : 
                             q_reg[15:12];

            // Update register
            q_reg <= {d3_next, d2_next, d1_next, d0_next};
        end
    end

endmodule

